const body = $input.first().json.body || $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenIds) staticData.seenIds = {};
if (!staticData.sessions) staticData.sessions = {};

const messages = [];
for (const entry of body.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    for (const msg of value.messages || []) {
      if (staticData.seenIds[msg.id]) continue;
      staticData.seenIds[msg.id] = Date.now();
      let text = null;
      if (msg.type === 'text') text = msg.text?.body || null;
      if (msg.type === 'button') text = msg.button?.text || msg.button?.payload || null;
      if (msg.type === 'interactive') {
        text = msg.interactive?.button_reply?.title
          || msg.interactive?.list_reply?.title
          || null;
      }
      if (!text) continue;
      messages.push({
        from: String(msg.from),
        id: msg.id,
        text: String(text).trim(),
        timestamp: msg.timestamp,
      });
    }
  }
}

const cutoff = Date.now() - 3600_000;
for (const [k, ts] of Object.entries(staticData.seenIds)) {
  if (ts < cutoff) delete staticData.seenIds[k];
}

if (!messages.length) return [];
return messages.map((m) => ({ json: m }));

/* n8n-qs-polyfill v2 */
function enc(v) {
  const s = String(v == null ? '' : v);
  try {
    if (typeof encodeURIComponent === 'function') return encodeURIComponent(s);
  } catch (_) {}
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    const ch = s[i];
    if (
      (c >= 48 && c <= 57) ||
      (c >= 65 && c <= 90) ||
      (c >= 97 && c <= 122) ||
      ch === '-' || ch === '_' || ch === '.' || ch === '~'
    ) {
      out += ch;
    } else if (c < 128) {
      out += '%' + c.toString(16).toUpperCase().padStart(2, '0');
    } else {
      const bytes = unescape(encodeURIComponent(ch));
      for (let j = 0; j < bytes.length; j++) {
        out += '%' + bytes.charCodeAt(j).toString(16).toUpperCase().padStart(2, '0');
      }
    }
  }
  return out;
}
if (typeof globalThis.URLSearchParams === 'undefined') {
  globalThis.URLSearchParams = class URLSearchParams {
    constructor(init) {
      this._p = [];
      if (typeof init === 'string') {
        String(init).replace(/^\?/, '').split('&').forEach((pair) => {
          if (!pair) return;
          const i = pair.indexOf('=');
          const k = i >= 0 ? pair.slice(0, i) : pair;
          const v = i >= 0 ? pair.slice(i + 1) : '';
          this._p.push([k, v]);
        });
      } else if (init && typeof init === 'object') {
        Object.keys(init).forEach((k) => this._p.push([String(k), String(init[k] == null ? '' : init[k])]));
      }
    }
    append(k, v) { this._p.push([String(k), String(v)]); }
    set(k, v) {
      const key = String(k);
      this._p = this._p.filter(([a]) => a !== key);
      this._p.push([key, String(v)]);
    }
    toString() {
      return this._p.map(([k, v]) => enc(k) + '=' + enc(v)).join('&');
    }
  };
}

