const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
if (!staticData.pendingBookings) staticData.pendingBookings = {};
if (!staticData.pendingByPhone) staticData.pendingByPhone = {};

const sessionKey = from;
if (!staticData.sessions[sessionKey]) staticData.sessions[sessionKey] = [];
const history = staticData.sessions[sessionKey];



function findPendingTokenForPhone(phone) {
  const mapped = staticData.pendingByPhone[phone];
  if (mapped && staticData.pendingBookings[mapped]) return mapped;
  // fallback: latest pending for this phone
  let best = null;
  let bestAt = 0;
  for (const [tok, p] of Object.entries(staticData.pendingBookings || {})) {
    if (p && p.phone === phone && Number(p.createdAt || 0) >= bestAt) {
      best = tok;
      bestAt = Number(p.createdAt || 0);
    }
  }
  return best;
}

function formatProposeReply(pending, token) {
  if (!pending) return null;
  return [
    '預約摘要（未扣積分）：',
    `${pending.courtName || pending.court}｜${pending.date} ${pending.startTime}-${pending.endTime}｜${pending.totalPlayers}人｜約 ${pending.estimatedPoints ?? '?'} 積分`,
    '請回覆「確認」兩字以完成預約。',
  ].join('\n');
}

async function executeCreateFromPending(token) {
  const pending = staticData.pendingBookings[token];
  if (!pending || pending.phone !== from) {
    return { ok: false, error: '搵唔到待確認嘅預約，請重新揀場同人數。' };
  }
  if (Date.now() - pending.createdAt > 30 * 60 * 1000) {
    delete staticData.pendingBookings[token];
    if (staticData.pendingByPhone[from] === token) delete staticData.pendingByPhone[from];
    return { ok: false, error: '確認已逾時，請重新查空缺再訂。' };
  }
  const players = Number(pending.totalPlayers);
  const res = await botPost.call(this, '/api/bot/booking', {
    phone: String(pending.phone || from),
    court: String(pending.court || ''),
    date: String(pending.date || '').slice(0, 10),
    startTime: String(pending.startTime || ''),
    endTime: String(pending.endTime || ''),
    totalPlayers: Number.isFinite(players) && players >= 1 && players <= 8 ? players : 1,
    includeSoloCourt: Boolean(pending.includeSoloCourt),
    source: 'whatsapp_bot',
  });
  if (res.status >= 400) {
    return { ok: false, error: explainBotError(res.data), raw: res.data };
  }
  delete staticData.pendingBookings[token];
  if (staticData.pendingByPhone[from] === token) delete staticData.pendingByPhone[from];
  return { ok: true, data: res.data.data || res.data };
}


function hongKongYearNow() {
  return Number(
    new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Hong_Kong', year: 'numeric' }).format(new Date())
  );
}

function pad2(n) {
  return String(n).padStart(2, '0');
}

function toHhMmFromDigits(raw) {
  const s = String(raw || '').replace(/\D/g, '');
  if (s.length === 3) return `${pad2(s.slice(0, 1))}:${s.slice(1)}`;
  if (s.length === 4) return `${s.slice(0, 2)}:${s.slice(2)}`;
  return null;
}

/** 從用戶文字抽日期／時段／分店線索（唔經 LLM） */
function parseUserBookingIntent(text) {
  const t = String(text || '');
  let date = null;
  const ymd = t.match(/(20\d{2})\s*[-\/.年]\s*(\d{1,2})\s*[-\/.月]\s*(\d{1,2})/);
  if (ymd) {
    date = `${ymd[1]}-${pad2(ymd[2])}-${pad2(ymd[3])}`;
  } else {
    const md = t.match(/(\d{1,2})\s*月\s*(\d{1,2})\s*[號号日]?/);
    if (md) date = `${hongKongYearNow()}-${pad2(md[1])}-${pad2(md[2])}`;
  }

  let startTime = null;
  let endTime = null;
  const colonRange = t.match(/(\d{1,2}):(\d{2})\s*[-–~到至]\s*(\d{1,2}):(\d{2})/);
  if (colonRange) {
    startTime = `${pad2(colonRange[1])}:${colonRange[2]}`;
    endTime = `${pad2(colonRange[3])}:${colonRange[4]}`;
  } else {
    const digitRange = t.match(/\b(\d{3,4})\s*[-–~到至]\s*(\d{3,4})\b/);
    if (digitRange) {
      startTime = toHhMmFromDigits(digitRange[1]);
      endTime = toHhMmFromDigits(digitRange[2]);
    } else {
      const one = t.match(/\b([01]?\d|2[0-3]):([0-5]\d)\b/) || t.match(/\b(\d{4})\b/);
      if (one) {
        startTime = one[2] != null ? `${pad2(one[1])}:${one[2]}` : toHhMmFromDigits(one[1]);
        // 預設 1 小時
        if (startTime) {
          const [h, m] = startTime.split(':').map(Number);
          const endM = h * 60 + m + 60;
          endTime = `${pad2(Math.floor(endM / 60) % 24)}:${pad2(endM % 60)}`;
          if (endM >= 24 * 60) endTime = '24:00';
        }
      }
    }
  }

  let storeQuery = '';
  if (/efx|vip\s*廂|vip廂/i.test(t)) storeQuery = '尖沙咀';
  else if (/尖沙咀|尖沙嘴|isquare|i-square|tst/i.test(t)) storeQuery = '尖沙咀';
  else if (/荔枝角|lck/i.test(t)) storeQuery = '荔枝角';

  const wantsAvailability = /有冇場|空缺|可唔可以book|想\s*book|訂場|預約|有沒有場/i.test(t);
  return { date, startTime, endTime, storeQuery, wantsAvailability };
}

function formatAvailabilityReply(data) {
  if (!data || typeof data !== 'object') return null;
  const storeName = data.store?.name || '分店';
  const date = data.date || '';
  const start = data.startTime || '';
  const end = data.endTime || '';
  const courts = Array.isArray(data.availableCourts) ? data.availableCourts : [];
  const lines = [];
  lines.push(`${date} ${storeName} ${start}-${end}`);
  if (!courts.length) {
    lines.push('呢個時段暫時冇空場。');
  } else {
    lines.push('可以 book：');
    for (const c of courts) {
      const name = c.courtName || '場地';
      const p = c.pricing || {};
      const cost = p.finalCost != null ? p.finalCost : p.totalPrice;
      const list = p.listPrice;
      if (cost != null && list != null && list !== cost) {
        lines.push(`• ${name} — ${cost} 積分（正價 ${list}）`);
      } else if (cost != null) {
        lines.push(`• ${name} — ${cost} 積分`);
      } else {
        lines.push(`• ${name}`);
      }
    }
  }
  if (data.member && data.member.matched === false) {
    const reg = data.registerUrl || 'https://picklevibes.hk/register';
    const site = data.courtsUrl || 'https://picklevibes.hk/courts';
    lines.push('');
    lines.push(`以上係正價。登記會員可享場租 8 折：${reg}`);
    lines.push(`亦可上網站查價／訂場：${site}`);
  } else if (data.member?.hasMemberDiscount && data.member?.discountLabel) {
    lines.push('');
    lines.push(`已套用：${data.member.discountLabel}`);
  }
  if (courts.length) {
    lines.push('');
    lines.push('想 book 邊個場？同埋幾多人（1–8）？');
  }
  return lines.join('\n');
}

function formatActivitiesReply(data) {
  if (!data || typeof data !== 'object') return null;
  const acts = Array.isArray(data.activities) ? data.activities : [];
  const lines = [];
  if (!acts.length) {
    lines.push('而家活動中心暫時冇即將開始、可報名嘅活動。');
    if (data.activitiesHubUrl) lines.push(`最新公布：${data.activitiesHubUrl}`);
    return lines.join('\n');
  }
  lines.push('活動中心近期可參加：');
  for (const a of acts.slice(0, 10)) {
    const bits = [a.title || '活動'];
    if (a.startAt) bits.push(a.startAt);
    if (a.location) bits.push(a.location);
    if (a.pricePoints != null) bits.push(`${a.pricePoints} 積分`);
    if (a.availableSpots != null) bits.push(`剩 ${a.availableSpots} 位`);
    lines.push(`• ${bits.join('｜')}`);
    if (a.detailUrl) lines.push(`  ${a.detailUrl}`);
  }
  return lines.join('\n');
}

async function requestJson(method, url, headers, bodyObj) {
  const opts = {
    method,
    url,
    headers: headers || {},
    json: true,
    timeout: 20000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  };
  if (bodyObj != null) {
    opts.body = bodyObj;
  }
  const res = await this.helpers.httpRequest.call(this, opts);
  // n8n may return { body, statusCode } or just body depending on version
  if (res && typeof res === 'object' && 'statusCode' in res) {
    return { status: res.statusCode, data: res.body };
  }
  return { status: 200, data: res };
}

