const systemPrompt = `你是 PickleVibes WhatsApp 客服（香港 24/7 智能匹克球）。繁中為主。簡短直接。

規則：
- 禁止估計價錢／空位／積分／日期／時間。缺資料就追問，唔好自行假設。
- 報場地費用必須用 check_availability 結果嘅 finalCost（或 totalPrice），原樣抄數字；可附 listPrice 作正價對照。禁止改價或改場名。
- 空缺列表由系統模板輸出：你 call 完 check_availability／list_activities 之後唔好自己重寫場名、價錢、年份；缺資料就追問，唔好估。
- 禁止寫 2023／2024 等舊年份；日期只可用用戶講嘅或工具返回嘅 date。
- 用戶只講月日時（例如「10月18號」），date 必須用今年（香港）年份，格式 YYYY-MM-DD；千萬唔好用 2023。
- 若 member.matched=false：講明以下係正價；提示登記會員可享場租 8 折並附 registerUrl；建議上 courtsUrl 查價／訂場。
- 查積分、空缺、訂場、活動必須先 call tools，只用工具結果回答。
- 禁止回「請等我查／正在查詢／稍等」這類進度句。用戶只會收到你這一則最終回覆，冇第二則跟進。
- 用戶只講分店（例如 iSQUARE／尖沙咀）但未講日期或時間 → 只問清楚日期同開始時間／時長，唔好 call availability。
- 「尖沙咀」「TST」「iSQUARE」都係同一間尖沙咀店；「荔枝角」「LCK」係總店。resolve_store／get_stores 會對地址同別名。
- 問活動／活動中心／有咩課／體驗班 → 必須 call list_activities，列出標題、時間、地點、費用、剩餘名額，並附上每項 detailUrl（完整連結）。唔好只叫人去官網而唔列活動；冇活動先講暫時冇可報名活動並可附 activitiesHubUrl。
- 工具失敗時，只可轉述工具返回的 error。
- USER_NOT_FOUND → 引導註冊 ${REGISTER_URL}，唔好訂場。
- 時長只可 1 或 2 小時。
- 訂場前用 propose_booking，等用戶回「確認」兩字先 create_booking。「好／ok／book」唔算確認。
- 禁止編造電話、電郵、網址。官方聯絡只可講：電話 +852 6190 2761，電郵 info@picklevibes.hk。網站 ${REGISTER_URL}。
- 當前用戶電話：${from}`;

history.push({ role: 'user', content: userText });
while (history.length > 16) history.shift();

const messages = [{ role: 'system', content: systemPrompt }, ...history];

// 用戶只回「確認」→ 唔經 LLM，直接用電話對應嘅 pending 落單
const confirmOnly = String(userText || '').replace(/\s/g, '');
if (confirmOnly === '確認' || confirmOnly.toLowerCase() === 'confirm') {
  const token = findPendingTokenForPhone(from);
  if (!token) {
    const miss = '搵唔到待確認嘅預約。請再講想訂邊個場、日期時間同人數，等我重新幫你暫存。';
    history.push({ role: 'assistant', content: miss });
    staticData.sessions[sessionKey] = history.slice(-16);
    return [{ json: { from, reply: miss, messageId } }];
  }
  const booked = await executeCreateFromPending.call(this, token);
  let replyText;
  if (booked.ok) {
    const d = booked.data || {};
    replyText = ('已確認預約成功。' + (d.courtName || d.court || '') + ' ' + (d.date || '') + ' ' + (d.startTime || '') + '-' + (d.endTime || '') + '。').replace(/\s+/g, ' ').trim();
    if (d.pointsDeducted != null) replyText += ' 已扣 ' + d.pointsDeducted + ' 積分。';
    else replyText += ' 詳情可上網站「我的預約」查看。';
  } else {
    replyText = booked.error || '確認預約失敗，請稍後再試。';
  }
  history.push({ role: 'assistant', content: replyText });
  staticData.sessions[sessionKey] = history.slice(-16);
  return [{ json: { from, reply: replyText.slice(0, 4000), messageId } }];
}


async function runTool(name, args) {
  try {
    if (name === 'get_balance') {
      const res = await botGet.call(this, `/api/bot/balance?phone=${enc(from)}`);
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'get_stores') {
      const res = await botGet.call(this, '/api/bot/stores');
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'resolve_store') {
      const res = await botGet.call(this, `/api/bot/stores/resolve?q=${enc(args.q || '')}`);
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'list_activities') {
      const parts = [];
      if (args.store) parts.push(`store=${enc(args.store)}`);
      if (args.limit) parts.push(`limit=${enc(String(args.limit))}`);
      const qs = parts.length ? `?${parts.join('&')}` : '';
      const res = await botGet.call(this, `/api/bot/activities${qs}`);
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'check_availability') {
      const parts = [
        `store=${enc(args.storeId || '')}`,
        `date=${enc(args.date || '')}`,
        `startTime=${enc(args.startTime || '')}`,
        `endTime=${enc(args.endTime || '')}`,
        `phone=${enc(from)}`,
      ];
      if (args.courtType) parts.push(`courtType=${enc(args.courtType)}`);
      const res = await botGet.call(this, `/api/bot/availability?${parts.join('&')}`);
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'propose_booking') {
      const courtId = String(args.courtId || '').trim();
      if (!/^[a-f0-9]{24}$/i.test(courtId)) {
        return { ok: false, error: '場地 ID 無效，請重新查空缺後再揀場。' };
      }
      let players = Number(args.totalPlayers);
      if (!Number.isFinite(players) || players < 1 || players > 8) players = 1;
      const dateStr = String(args.date || '').trim().slice(0, 10);
      const startTime = String(args.startTime || '').trim();
      const endTime = String(args.endTime || '').trim();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr) || !startTime || !endTime) {
        return { ok: false, error: '日期或時間不完整，請重新查空缺。' };
      }
      const token = `pb_${from}_${Date.now()}`;
      staticData.pendingBookings[token] = {
        phone: from,
        court: courtId,
        courtName: args.courtName || '',
        date: dateStr,
        startTime,
        endTime,
        totalPlayers: players,
        estimatedPoints: args.estimatedPoints,
        includeSoloCourt: Boolean(args.includeSoloCourt),
        createdAt: Date.now(),
      };
      staticData.pendingByPhone[from] = token;
      return {
        ok: true,
        data: {
          confirmToken: token,
          summary: `${args.courtName || courtId}｜${dateStr} ${startTime}-${endTime}｜${players}人｜約 ${args.estimatedPoints ?? '?'} 積分`,
          instruction: '請用戶只回覆「確認」兩字；系統會自動完成預約。',
        },
      };
    }
    if (name === 'create_booking') {
      const normalized = String(userText || '').replace(/\s/g, '');
      const confirmed = normalized === '確認' || normalized.toLowerCase() === 'confirm';
      if (!confirmed) {
        return { ok: false, error: '用戶本則訊息未包含「確認」，不可扣積分。請先請用戶回覆「確認」。' };
      }
      const token = args.confirmToken || findPendingTokenForPhone(from);
      if (!token || !staticData.pendingBookings[token]) {
        return { ok: false, error: '搵唔到待確認嘅預約，請重新揀場同人數後再確認。' };
      }
      return await executeCreateFromPending.call(this, token);
    }
    return { ok: false, error: `未知工具 ${name}` };
  } catch (e) {
    return { ok: false, error: e.message || String(e) };
  }
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function isRetryableAiStatus(status) {
  return status === 429 || status === 408 || status >= 500;
}

function aiErrorText(aiRes) {
  return aiRes?.data?.error?.message || aiRes?.data?.message || JSON.stringify(aiRes?.data || {}).slice(0, 300);
}

async function callChatCompletions(model) {
  return requestJson.call(
    this,
    'POST',
    `${OPENAI_BASE}/chat/completions`,
    { Authorization: `Bearer ${OPENAI_KEY}`, 'Content-Type': 'application/json' },
    {
      model,
      messages,
      tools,
      tool_choice: 'auto',
      temperature: 0.1,
    }
  );
}


// 用戶訊息已有日期＋時段 → 直接查空缺（唔靠 LLM 抽欄位，避免死循環）
const intent = parseUserBookingIntent(userText);
if (intent.wantsAvailability && intent.date && intent.startTime && intent.endTime) {
  try {
    let storeId = '';
    const q = intent.storeQuery || '尖沙咀';
    const resolved = await runTool.call(this, 'resolve_store', { q });
    if (resolved?.ok && resolved.data?.id) storeId = String(resolved.data.id);
    if (!storeId) {
      const stores = await runTool.call(this, 'get_stores', {});
      const list = stores?.data?.stores || stores?.data || [];
      const hit = (Array.isArray(list) ? list : []).find((s) =>
        /isquare|尖沙咀|iSQUARE/i.test(`${s.name || ''}${s.slug || ''}${s.address || ''}`)
      );
      if (hit) storeId = String(hit.id || hit._id || '');
    }
    if (storeId) {
      const avail = await runTool.call(this, 'check_availability', {
        storeId,
        date: intent.date,
        startTime: intent.startTime,
        endTime: intent.endTime,
      });
      if (avail?.ok && avail.data) {
        const replyText = formatAvailabilityReply(avail.data) || '查詢完成，但暫時冇可顯示場地。';
        history.push({ role: 'assistant', content: replyText });
        staticData.sessions[sessionKey] = history.slice(-16);
        return [{ json: { from, reply: replyText.slice(0, 4000), messageId } }];
      }
      const errText = avail?.error || '查空缺失敗，請稍後再試。';
      history.push({ role: 'assistant', content: errText });
      staticData.sessions[sessionKey] = history.slice(-16);
      return [{ json: { from, reply: errText, messageId } }];
    }
  } catch (e) {
    console.log('early availability error', e.message || e);
  }
}

let reply = '系統暫時忙碌，請稍後再試。如需協助可致電 +852 6190 2761。';
let lastAvailability = null;
let lastActivities = null;
let lastPropose = null;
let lastCreateResult = null;
let lastToolHadFailure = false;
let activeModel = MODEL_CHAIN[0];
let modelIndex = 0;
let lastAiError = '';

for (let round = 0; round < 8; round++) {
  let aiRes = await callChatCompletions.call(this, activeModel);

  // retry once on rate-limit / upstream blip
  if (aiRes.status >= 400 && isRetryableAiStatus(aiRes.status)) {
    await sleep(1200);
    aiRes = await callChatCompletions.call(this, activeModel);
  }

  // switch to next fallback model
  while (aiRes.status >= 400 && modelIndex < MODEL_CHAIN.length - 1) {
    lastAiError = `model=${activeModel} status=${aiRes.status} ${aiErrorText(aiRes)}`;
    modelIndex += 1;
    activeModel = MODEL_CHAIN[modelIndex];
    await sleep(400);
    aiRes = await callChatCompletions.call(this, activeModel);
    if (aiRes.status >= 400 && isRetryableAiStatus(aiRes.status)) {
      await sleep(1200);
      aiRes = await callChatCompletions.call(this, activeModel);
    }
  }

  if (aiRes.status >= 400) {
    lastAiError = `model=${activeModel} status=${aiRes.status} ${aiErrorText(aiRes)}`;
    console.log('AI all models failed:', lastAiError);
    reply = '系統暫時忙碌，請稍後再試。如需協助可致電 +852 6190 2761。';
    break;
  }

  const choice = aiRes.data?.choices?.[0]?.message;
  if (!choice) {
    // empty response: try next model once
    if (modelIndex < MODEL_CHAIN.length - 1) {
      modelIndex += 1;
      activeModel = MODEL_CHAIN[modelIndex];
      continue;
    }
    reply = '暫時未能產生回覆，請稍後再試。';
    break;
  }

  messages.push(choice);

  const toolCalls = choice.tool_calls || [];
  if (!toolCalls.length) {
    let text = String(choice.content || '').trim() || '收到。';
    const fakeProgress = /(正在查詢|請稍等|請等我|幫你查下|查詢空缺|稍等～|稍等~)/.test(text);
    // 有 tool 真實資料 → 用固定模板回覆，避免 LLM 改年份／價錢／場名
    const availText = formatAvailabilityReply(lastAvailability);
    const actsText = formatActivitiesReply(lastActivities);
    if (availText) {
      text = availText;
    } else if (actsText) {
      text = actsText;
    } else if (fakeProgress) {
      text = '想幫你查分店空缺，請話我知日期（例如 2026-10-18）、開始時間、想訂幾耐（1 或 2 小時）。';
      messages.pop();
    } else if (lastToolHadFailure && (!text || text.length < 8)) {
      text = '查詢失敗，請稍後再試，或上 https://picklevibes.hk/courts 睇空缺。';
    }
    // （已移除舊年份攔截：會誤傷正常對話做成死循環）
    reply = text;
    history.push({ role: 'assistant', content: reply });
    break;
  }

  for (const tc of toolCalls) {
    let args = {};
    try { args = JSON.parse(tc.function?.arguments || '{}'); } catch { args = {}; }
    const result = await runTool.call(this, tc.function?.name, args);
    if (result && result.ok === false) lastToolHadFailure = true;
    if (tc.function?.name === 'check_availability' && result?.ok && result.data) {
      lastAvailability = result.data;
    }
    if (tc.function?.name === 'list_activities' && result?.ok && result.data) {
      lastActivities = result.data;
    }
    if (tc.function?.name === 'propose_booking' && result?.ok && result.data) {
      lastPropose = result.data;
    }
    if (tc.function?.name === 'create_booking') {
      lastCreateResult = result;
    }
    messages.push({
      role: 'tool',
      tool_call_id: tc.id,
      content: JSON.stringify(result),
    });
  }

  // 優先：落單／暫存；空缺模板次之（避免蓋過確認）
  if (lastCreateResult) {
    if (lastCreateResult.ok) {
      const d = lastCreateResult.data || {};
      reply = ('已確認預約成功。' + (d.courtName || '') + ' ' + (d.date || '') + ' ' + (d.startTime || '') + '-' + (d.endTime || '') + '。').replace(/\s+/g, ' ').trim();
      if (d.pointsDeducted != null) reply += ' 已扣 ' + d.pointsDeducted + ' 積分。';
    } else {
      reply = lastCreateResult.error || '確認預約失敗，請重新揀場。';
    }
    history.push({ role: 'assistant', content: reply });
    break;
  }
  if (lastPropose) {
    const tok = lastPropose.confirmToken;
    const pending = tok ? staticData.pendingBookings[tok] : null;
    reply = formatProposeReply(pending, tok) || lastPropose.summary || '已暫存預約，請回覆「確認」。';
    history.push({ role: 'assistant', content: reply });
    break;
  }
  if (lastAvailability) {
    const availText = formatAvailabilityReply(lastAvailability);
    if (availText) {
      reply = availText;
      history.push({ role: 'assistant', content: reply });
      break;
    }
  }
  if (lastActivities) {
    const actsText = formatActivitiesReply(lastActivities);
    if (actsText) {
      reply = actsText;
      history.push({ role: 'assistant', content: reply });
      break;
    }
  }
}

staticData.sessions[sessionKey] = history.slice(-16);

return [{ json: { from, reply: reply.slice(0, 4000), messageId } }];
